import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import InputField from '../../../components/ui/InputField/InputField';
import Button from '../../../components/ui/Button/Button';

const CreateAdminPage = () => {
  return (
    <ContentWrapper title="Cadastrar Admin Nível 1">
      <form>
        <InputField label="Nome Completo" name="name" placeholder="Nome do administrador" />
        <InputField label="Email" type="email" name="email" placeholder="email@exemplo.com" />
        <InputField label="Senha Provisória" type="password" name="password" />
        <Button type="submit">Cadastrar Administrador</Button>
      </form>
    </ContentWrapper>
  );
};

export default CreateAdminPage;
